BEGIN;CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS wellness_tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wellness_identities(tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),subject text NOT NULL,role text NOT NULL CHECK(role IN('member','coach','operator')),email text,active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,subject));
CREATE TABLE IF NOT EXISTS wellness_coaches(tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),coach_subject text NOT NULL,specialties text[] NOT NULL DEFAULT '{}',capacity integer NOT NULL CHECK(capacity>=0),active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,coach_subject));
CREATE TABLE IF NOT EXISTS wellness_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),member_subject text NOT NULL,coach_subject text NOT NULL,program_name text NOT NULL,state text NOT NULL DEFAULT 'PENDING_PAYMENT',price_cents integer NOT NULL CHECK(price_cents>0),consent_version text NOT NULL,consented_at timestamptz NOT NULL,consent_revoked_at timestamptz,readiness_answers jsonb NOT NULL,idempotency_key text NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,member_subject,idempotency_key));
CREATE TABLE IF NOT EXISTS wellness_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),enrollment_id uuid NOT NULL UNIQUE REFERENCES wellness_enrollments(id),title text NOT NULL,plan_payload jsonb NOT NULL,state text NOT NULL DEFAULT 'ACTIVE' CHECK(state IN('ACTIVE','SAFETY_HOLD','COMPLETED')),version integer NOT NULL DEFAULT 1,updated_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wellness_goals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),enrollment_id uuid NOT NULL REFERENCES wellness_enrollments(id),title text NOT NULL,metric text NOT NULL,target_value text NOT NULL,progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),version integer NOT NULL DEFAULT 1,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wellness_check_ins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),enrollment_id uuid NOT NULL REFERENCES wellness_enrollments(id),pain integer NOT NULL CHECK(pain BETWEEN 0 AND 10),energy integer NOT NULL CHECK(energy BETWEEN 1 AND 5),mood integer NOT NULL CHECK(mood BETWEEN 1 AND 5),adherence integer NOT NULL CHECK(adherence BETWEEN 0 AND 100),chest_pain boolean NOT NULL DEFAULT false,fainting boolean NOT NULL DEFAULT false,evidence text NOT NULL,rule_version text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wellness_safety_alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),enrollment_id uuid NOT NULL REFERENCES wellness_enrollments(id),check_in_id uuid NOT NULL REFERENCES wellness_check_ins(id),rule_code text NOT NULL,severity text NOT NULL CHECK(severity IN('HIGH','CRITICAL')),message text NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','ACKNOWLEDGED','RESOLVED')),disposition text,coach_note text,acknowledged_by text,acknowledged_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wellness_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),enrollment_id uuid NOT NULL REFERENCES wellness_enrollments(id),check_in_id uuid NOT NULL REFERENCES wellness_check_ins(id),rule_code text NOT NULL,recommendation text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED')),decided_by text,decision_note text,decided_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wellness_wearable_observations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),enrollment_id uuid NOT NULL REFERENCES wellness_enrollments(id),provider text NOT NULL,source_event_id text NOT NULL,metric text NOT NULL,value numeric NOT NULL,unit text NOT NULL,observed_at timestamptz NOT NULL,quality text NOT NULL DEFAULT 'provider-reported',received_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider,source_event_id,metric));
ALTER TABLE wellness_wearable_observations ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS wellness_appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),enrollment_id uuid NOT NULL REFERENCES wellness_enrollments(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'VIDEO_PENDING' CHECK(state IN('VIDEO_PENDING','CONFIRMED','PROVIDER_FAILED','COMPLETED','CANCELLED')),agenda text NOT NULL,meeting_url text,provider_meeting_id text,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS wellness_provider_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),enrollment_id uuid REFERENCES wellness_enrollments(id),appointment_id uuid REFERENCES wellness_appointments(id),provider text NOT NULL CHECK(provider IN('billing','video','wearable','notification')),operation text NOT NULL,idempotency_key text NOT NULL,request_payload jsonb NOT NULL,response_payload jsonb,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','retryable','dead-letter')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider,idempotency_key));
CREATE TABLE IF NOT EXISTS wellness_webhook_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),provider text NOT NULL,delivery_id text NOT NULL,body_sha256 text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider,delivery_id));
CREATE TABLE IF NOT EXISTS wellness_restore_drills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),backup_reference text NOT NULL,status text NOT NULL CHECK(status IN('scheduled','passed','failed')),evidence_uri text,recorded_by text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wellness_audit_events(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES wellness_tenants(id),actor_subject text NOT NULL,action text NOT NULL,resource_type text NOT NULL,resource_id uuid,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION reject_wellness_audit_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'wellness audit is append-only';END;$$;DROP TRIGGER IF EXISTS wellness_audit_immutable ON wellness_audit_events;CREATE TRIGGER wellness_audit_immutable BEFORE UPDATE OR DELETE ON wellness_audit_events FOR EACH ROW EXECUTE FUNCTION reject_wellness_audit_mutation();
CREATE INDEX IF NOT EXISTS wellness_enrollment_actor_idx ON wellness_enrollments(tenant_id,member_subject,coach_subject,created_at DESC);CREATE INDEX IF NOT EXISTS wellness_jobs_due_idx ON wellness_provider_jobs(status,next_attempt_at);CREATE INDEX IF NOT EXISTS wellness_alerts_open_idx ON wellness_safety_alerts(tenant_id,status,severity);
COMMIT;
